ThreadMXBean bean=ManagementFactory.getThreadMXBean();
ThreadInfo[] infos=bean.dumpAllThreads(true,true);
for(ThreadInfo i:infos){System.out.printf("\"%s\" %s lock=%s owner=%s%n",i.getThreadName(),i.getThreadState(),i.getLockName(),i.getLockOwnerName());for(StackTraceElement e:i.getStackTrace())System.out.println("  at "+e);}

ThreadMXBean bean=ManagementFactory.getThreadMXBean();
long[] ids=bean.findDeadlockedThreads();
if(ids!=null) for(ThreadInfo i:bean.getThreadInfo(ids,true,true)) System.out.printf("%s waits %s owned by %s%n",i.getThreadName(),i.getLockName(),i.getLockOwnerName());
// Test musi mieć timeout, a celowo zakleszczone wątki powinny być daemonami lub działać w osobnym procesie.

